import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.DYPTBNgj.js";const m=JSON.parse('{"title":"Why Aerini is dual-licensed","description":"","frontmatter":{},"headers":[],"relativePath":"dual-licensing.md","filePath":"dual-licensing.md"}'),r={name:"dual-licensing.md"};function o(s,e,l,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="why-aerini-is-dual-licensed" tabindex="-1">Why Aerini is dual-licensed <a class="header-anchor" href="#why-aerini-is-dual-licensed" aria-label="Permalink to &quot;Why Aerini is dual-licensed&quot;">​</a></h1><p>Aerini ships under two licenses at once: AGPL-3.0 for open source use, and a separate commercial license for anyone who needs to get out from under AGPL&#39;s copyleft obligation. This page explains why that&#39;s the model, not just that it exists.</p><h2 id="the-problem-a-single-license-can-t-solve" tabindex="-1">The problem a single license can&#39;t solve <a class="header-anchor" href="#the-problem-a-single-license-can-t-solve" aria-label="Permalink to &quot;The problem a single license can&#39;t solve&quot;">​</a></h2><p>AGPL-3.0 is a strong copyleft license: if you run a modified version of <code>aerini-server</code> as a network-accessible service, you have to publish those modifications under AGPL-3.0 too. That&#39;s the right default for keeping Aerini and its ecosystem open. It&#39;s also a dealbreaker for some companies — building a closed-source product on top of Aerini, or shipping a modified version to clients without disclosing the changes, isn&#39;t compatible with AGPL on its own.</p><p>A commercial license removes that obligation for those cases, for one named product or service per license. That product can have any number of end customers; each additional product needs its own license. No source disclosure required, proprietary modifications permitted. See <a href="https://github.com/Panchak2d/Aerini/blob/main/FUNDING.md" target="_blank" rel="noreferrer">FUNDING.md</a> for what it&#39;s actually for and who needs one.</p><h2 id="why-that-requires-a-cla" tabindex="-1">Why that requires a CLA <a class="header-anchor" href="#why-that-requires-a-cla" aria-label="Permalink to &quot;Why that requires a CLA&quot;">​</a></h2><p>Offering a commercial license only works if the maintainer actually has the right to relicense the whole codebase that way — including every contribution in it, not just the parts written by the maintainer. Without a Contributor License Agreement, an outside contribution could only ever go out under AGPL-3.0, since nothing would grant the maintainer the separate right to sublicense it commercially. That would fragment the codebase into &quot;parts we can dual-license&quot; and &quot;parts we can&#39;t,&quot; which isn&#39;t workable.</p><p>The CLA solves this the same way most dual-licensed open source projects do: contributors grant the maintainer a non-exclusive license broad enough to support both tracks, while keeping full ownership and reuse rights over their own contribution. See <a href="https://github.com/Panchak2d/Aerini/blob/main/CLA-SUMMARY.md" target="_blank" rel="noreferrer">CLA-SUMMARY.md</a> for the plain-English breakdown, or <a href="https://github.com/Panchak2d/Aerini/blob/main/CLA.md" target="_blank" rel="noreferrer">CLA.md</a> Section 2 for the binding terms.</p><h2 id="what-this-doesn-t-change" tabindex="-1">What this doesn&#39;t change <a class="header-anchor" href="#what-this-doesn-t-change" aria-label="Permalink to &quot;What this doesn&#39;t change&quot;">​</a></h2><ul><li>Contributions already released under AGPL-3.0 stay available under AGPL-3.0 — that grant is irrevocable.</li><li>The AGPL-3.0 release isn&#39;t a &quot;free tier&quot; that could disappear if commercial licensing takes off. It&#39;s the default distribution channel, not a promotion.</li><li>Signing the CLA doesn&#39;t transfer ownership, create an employment relationship, or entitle a contributor to commercial licensing revenue.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="https://github.com/Panchak2d/Aerini/blob/main/CLA-SUMMARY.md" target="_blank" rel="noreferrer">CLA-SUMMARY.md</a> — plain-English CLA summary and FAQ</li><li><a href="https://github.com/Panchak2d/Aerini/blob/main/CLA.md" target="_blank" rel="noreferrer">CLA.md</a> — the binding agreement</li><li><a href="https://github.com/Panchak2d/Aerini/blob/main/FUNDING.md" target="_blank" rel="noreferrer">FUNDING.md</a> — commercial licensing and supporting the project</li></ul>',12)])])}const p=a(r,[["render",o]]);export{m as __pageData,p as default};
